'use client';

import {
  Fragment,
  startTransition,
  useActionState,
  useEffect,
  useId,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { notificationDate } from '../lib/notification-list';
import {
  RETRY_REASONS,
  RETRY_STATES,
  retryFailure,
  type NotificationRetryState,
} from '../lib/notification-retry';

type RetryAction = (
  previous: NotificationRetryState,
  form: FormData,
) => Promise<NotificationRetryState>;

export function NotificationRetryListRefresh({ firstHref }: { firstHref: string }) {
  // Only the fixed first-page status generated by the server is a recovery target.
  if (!/^\/ops\/notifications\?status=(all|pending|sent|failed)$/.test(firstHref)) return null;
  return (
    <p>
      通知の状態と試行数は、一覧を更新すると反映されます。 <a href={firstHref}>一覧を最新にする</a>
    </p>
  );
}

/** A row owns its confirmation; no recipient or free resource identifier is rendered. */
export function NotificationRetryForm({
  summary,
  description,
  action,
  children,
  firstHref,
}: {
  summary: 'check_required' | 'reserved' | 'unavailable';
  description: string;
  action: RetryAction;
  children: ReactNode;
  firstHref: string;
}) {
  const id = useId();
  const [open, setOpen] = useState(false);
  const [ready, setReady] = useState(false);
  const entry = useRef<HTMLButtonElement>(null);
  const result = useRef<HTMLDivElement>(null);
  const submitting = useRef(false);
  const [state, dispatch, pending] = useActionState<NotificationRetryState, FormData>(
    async (previous, form) => {
      try {
        return await action(previous, form);
      } catch {
        return { message: retryFailure(503), mustCheck: true, attempt: previous.attempt + 1 };
      }
    },
    { message: '', attempt: 0 },
  );
  useEffect(() => setReady(true), []);
  useEffect(() => {
    if (!pending) {
      submitting.current = false;
      if (open && state.attempt) result.current?.focus();
    }
  }, [pending, state.attempt, open]);
  function invoke(intent: 'check' | 'reserve') {
    if (!ready || pending || submitting.current || state.scopeChanged) return;
    submitting.current = true;
    setOpen(true);
    const form = new FormData();
    form.set('intent', intent);
    if (intent === 'reserve' && state.data?.version) form.set('version', state.data.version);
    startTransition(() => dispatch(form));
  }
  const canReserve =
    state.data?.eligible &&
    state.data.state === 'not_requested' &&
    !state.mustCheck &&
    !state.message;
  return (
    <Fragment>
      <tr>
        {children}
        <td className="notification-retry-cell">
          {summary === 'unavailable' ? (
            <span className="hint">手動再試行の対象外</span>
          ) : (
            <button
              type="button"
              ref={entry}
              className="secondary"
              aria-expanded={open}
              aria-controls={open ? id : undefined}
              disabled={!ready || pending || state.scopeChanged}
              onClick={() => invoke('check')}
            >
              {summary === 'reserved' ? '予約状態を確認' : '再試行を確認'}
            </button>
          )}
        </td>
      </tr>
      {open && (
        <tr className="notification-retry-row">
          <td colSpan={5}>
            <section
              id={id}
              className="notification-retry"
              aria-label="通知の手動再試行"
              aria-busy={pending}
            >
              <p className="notification-retry-target">{description}</p>
              {pending ? (
                <p role="status">予約状態を確認しています…</p>
              ) : (
                <div
                  ref={result}
                  tabIndex={-1}
                  className="notification-retry-result"
                  role={state.message ? 'alert' : 'status'}
                >
                  <h2>
                    {state.message
                      ? '予約状態の確認が必要です'
                      : canReserve
                        ? 'この通知の再試行を予約しますか'
                        : state.data
                          ? RETRY_STATES[state.data.state]
                          : '予約状態を確認してください'}
                  </h2>
                  {state.message && <p>{state.message}</p>}
                  {state.data?.reason && <p>{RETRY_REASONS[state.data.reason]}</p>}
                  {state.data?.requestedAt && (
                    <p>
                      予約日時{' '}
                      <time dateTime={state.data.requestedAt}>
                        {notificationDate(state.data.requestedAt)}
                      </time>
                    </p>
                  )}
                  {state.data?.expiresAt && (
                    <p>
                      実行の有効期限{' '}
                      <time dateTime={state.data.expiresAt}>
                        {notificationDate(state.data.expiresAt)}
                      </time>
                    </p>
                  )}
                  {state.data?.completedAt && (
                    <p>
                      結果の記録日時{' '}
                      <time dateTime={state.data.completedAt}>
                        {notificationDate(state.data.completedAt)}
                      </time>
                    </p>
                  )}
                  {state.data && state.data.state !== 'not_requested' && (
                    <p>この通知への予約は1回限りです。追加の予約はできません。</p>
                  )}
                  {state.data && state.data.state !== 'not_requested' && (
                    <NotificationRetryListRefresh firstHref={firstHref} />
                  )}
                  {state.data?.state === 'succeeded' && (
                    <p>記録処理が完了しました。実際のメール配達は確認できません。</p>
                  )}
                  {/ログイン/.test(state.message) && (
                    <p>
                      <a href="/login" target="_blank" rel="noopener">
                        別のタブでログインする
                      </a>
                    </p>
                  )}
                </div>
              )}
              {canReserve && !pending && (
                <div className="notification-retry-confirmation">
                  <p>
                    この通知に限り、追加の記録処理を1回予約します。予約は1回限りで、実行開始までの有効期限は15分です。開始時刻は保証されません。
                  </p>
                  <p>
                    メール通知設定のOFFは新しい通知に適用されます。この既存通知の再試行には適用されません。処理開始後の取消はできません。
                  </p>
                  <p>開発環境では送信処理の記録のみです。予約は配達完了を意味しません。</p>
                </div>
              )}
              <div className="notification-retry-actions">
                {canReserve && (
                  <form
                    onSubmit={(event) => {
                      event.preventDefault();
                      invoke('reserve');
                    }}
                    aria-label="手動再試行の予約"
                  >
                    <button type="submit" disabled={pending}>
                      {pending ? '予約しています…' : '再試行を予約'}
                    </button>
                  </form>
                )}
                {!state.scopeChanged && (
                  <button
                    type="button"
                    className="secondary"
                    disabled={pending}
                    onClick={() => invoke('check')}
                  >
                    予約状態を再確認
                  </button>
                )}
                {state.scopeChanged && <a href={firstHref}>現在の組織で一覧を開き直す</a>}
                <button
                  type="button"
                  className="secondary"
                  disabled={pending}
                  onClick={() => {
                    setOpen(false);
                    entry.current?.focus();
                  }}
                >
                  閉じる
                </button>
              </div>
            </section>
          </td>
        </tr>
      )}
    </Fragment>
  );
}
